import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cute_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B);
"""

cute_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Tiled GEMM kernel computing C = A @ B
// A: (M, K) row-major
// B: (K, N) row-major
// C: (M, N) row-major
template <class TA, class TB, class TC>
__global__ static void
gemm_nn_device(int M, int N, int K,
               TA const* __restrict__ A,
               TB const* __restrict__ B,
               TC* __restrict__ C)
{
  // Logical global-memory tensors.
  // mA: direct (M,K) row-major view of A.
  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(M, K), make_stride(K, Int<1>{}));

  // mB: (N,K) "transpose view" of the physically (K,N) row-major B, i.e.
  // mB(n,k) reads B[k][n]. This lets us use the same (row, K) tiling
  // convention for both operands without any data movement.
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(N, K), make_stride(Int<1>{}, N));

  // mC: direct (M,N) row-major view of C.
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(M, N), make_stride(N, Int<1>{}));

  // CTA tile shape: (BLK_M, BLK_N, BLK_K)
  auto cta_tiler = make_shape(Int<128>{}, Int<128>{}, Int<8>{});
  auto cta_coord = make_coord(blockIdx.x, blockIdx.y, _);

  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1, X, _1>{});  // (BLK_M, BLK_K, k_tiles)
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step<X, _1, _1>{});  // (BLK_N, BLK_K, k_tiles)
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1, _1, X>{});  // (BLK_M, BLK_N)

  // Double-buffered shared memory tiles to enable pipelined (software-
  // pipelined) loads: while the current tile is being consumed by the
  // gemm() compute, the next tile's global->shared copy is issued into
  // the alternate buffer, letting the compiler/hardware overlap the
  // memory latency of the next load with the independent compute of the
  // current tile.
  __shared__ TA smemA[2][128 * 8];
  __shared__ TB smemB[2][128 * 8];
  Tensor sA0 = make_tensor(make_smem_ptr(smemA[0]), make_shape(Int<128>{}, Int<8>{}));
  Tensor sA1 = make_tensor(make_smem_ptr(smemA[1]), make_shape(Int<128>{}, Int<8>{}));
  Tensor sB0 = make_tensor(make_smem_ptr(smemB[0]), make_shape(Int<128>{}, Int<8>{}));
  Tensor sB1 = make_tensor(make_smem_ptr(smemB[1]), make_shape(Int<128>{}, Int<8>{}));
  // Thread layouts for cooperative load and compute
  auto tA = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tB = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));
  Tensor tAgA = local_partition(gA, tA, threadIdx.x);
  Tensor tBgB = local_partition(gB, tB, threadIdx.x);
  Tensor tAsA0 = local_partition(sA0, tA, threadIdx.x);
  Tensor tAsA1 = local_partition(sA1, tA, threadIdx.x);
  Tensor tBsB0 = local_partition(sB0, tB, threadIdx.x);
  Tensor tBsB1 = local_partition(sB1, tB, threadIdx.x);
  Tensor tCsA0 = local_partition(sA0, tC, threadIdx.x, Step<_1, X>{});
  Tensor tCsA1 = local_partition(sA1, tC, threadIdx.x, Step<_1, X>{});
  Tensor tCsB0 = local_partition(sB0, tC, threadIdx.x, Step<X, _1>{});
  Tensor tCsB1 = local_partition(sB1, tC, threadIdx.x, Step<X, _1>{});
  Tensor tCgC = local_partition(gC, tC, threadIdx.x, Step<_1, _1>{});
  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);
  int k_tile_max = size<2>(tAgA);
  // Prologue: prefetch the first tile into buffer 0.
  copy(tAgA(_, _, 0), tAsA0);
  copy(tBgB(_, _, 0), tBsB0);
  __syncthreads();
  int cur = 0;
  for (int k_tile = 0; k_tile < k_tile_max; ++k_tile) {
    int nxt = cur ^ 1;
    // Issue the next tile's global->shared copy into the alternate
    // buffer before consuming the current tile. This is independent
    // of the upcoming gemm() call on the current buffer, allowing the
    // load latency to be hidden behind the compute.
    if (k_tile + 1 < k_tile_max) {
      if (nxt == 0) {
        copy(tAgA(_, _, k_tile + 1), tAsA0);
        copy(tBgB(_, _, k_tile + 1), tBsB0);
      } else {
        copy(tAgA(_, _, k_tile + 1), tAsA1);
        copy(tBgB(_, _, k_tile + 1), tBsB1);
      }
    }
    if (cur == 0) {
      gemm(tCsA0, tCsB0, tCrC);
    } else {
      gemm(tCsA1, tCsB1, tCrC);
    }
    __syncthreads();
    cur = nxt;
  }
  // Epilogue: write result to global memory
  axpby(1.0f, tCrC, 0.0f, tCgC);
}

torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");

  int M = (int)A.size(0);
  int K = (int)A.size(1);
  int N = (int)B.size(1);
  TORCH_CHECK((int)B.size(0) == K, "Inner dimensions of A and B must match");

  TORCH_CHECK(M % 128 == 0 && N % 128 == 0 && K % 8 == 0,
              "This kernel requires M,N multiples of 128 and K multiple of 8");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C = torch::empty({M, N}, A.options());

  dim3 block(256);
  dim3 grid(M / 128, N / 128);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  gemm_nn_device<float, float, float><<<grid, block, 0, stream>>>(
      M, N, K,
      A_c.data_ptr<float>(),
      B_c.data_ptr<float>(),
      C.data_ptr<float>());

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE gemm launch failed: ", cudaGetErrorString(err));

  return C;
}
"""

cute_matmul_ext = load_inline(
    name="cute_matmul_ext",
    cpp_sources=cute_cpp_decl,
    cuda_sources=cute_cuda_src,
    functions=["cute_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Square matrix multiplication C = A @ B implemented with a single
    custom tiled CUTE GEMM kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_matmul_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matmul(A.contiguous(), B.contiguous())

